package com.vandorlabs.neoforge.screen;
import com.google.gson.*;
import com.vandorlabs.screen.*;
import com.vandorlabs.persistence.FrameSettings;
import com.vandorlabs.neoforge.ModernHousingTags;
import net.minecraft.nbt.*;
public final class ScreenActivationEditChecks {
 public static void main(String[] args)throws Exception{JsonObject reference;try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty("screenActivationEditsReference")))){reference=JsonParser.parseReader(reader).getAsJsonObject();}int cases=0;var catalog=NativeScreenCatalog.INSTANCE;for(var entry:reference.getAsJsonArray("cases")){var row=entry.getAsJsonObject();var family=ScreenFamily.fromId(row.get("id").getAsString());var before=TagParser.parseTag(row.get("before").getAsString());var expected=TagParser.parseTag(row.get("after").getAsString());var settings=NativeScreenSettings.read(before,catalog);var frames=FrameSettings.read(new ModernHousingTags(before),catalog::validFrame,catalog::validFrameSurface,catalog::validMaterial);var signature=NativeScreenJoining.signature(family,settings,frames,java.util.List.of(NativeScreenControls.read(before.getCompound("RedstonePrimary"),family.standaloneControlRows(0)),NativeScreenControls.read(before.getCompound("RedstoneSecondary"),family.standaloneControlRows(1))),catalog);var edit=new NativeScreenActivationEdit(row.get("mode").getAsInt(),row.get("state").getAsInt(),row.get("texture").getAsInt(),row.get("playback").getAsInt(),row.get("speed").getAsInt(),row.get("inverted").getAsBoolean());var result=edit.apply(family,settings,signature,catalog);var actual=new CompoundTag();result.write(actual);for(String key:java.util.List.of("DisplayActivation","RedstoneInverted","redstoneEnabled"))if(!java.util.Objects.equals(actual.get(key),expected.get(key)))throw new AssertionError("Source activation differs case="+cases+" key="+key+" actual="+actual.get(key)+" expected="+expected.get(key));cases++;}if(cases!=1344||!reference.get("sha256").getAsString().equals("5e28f94584eea5e3c38a56b1d45e417552c4032aa5fceaa274d9c7ad78c71b58"))throw new AssertionError("Source activation coverage");System.out.println("Native Screen activation edits PASS actual Source transitions="+cases);}
}
